package com.example.editor.grammar.provider.antlr;

import java.util.*;
import org.springframework.stereotype.Component;
import com.example.editor.grammar.GrammarProperties;
import com.example.editor.grammar.core.*;
import com.example.editor.grammar.provider.*;

/** ANTLR 4 provider. Parse trees only become HYDRA semantics through an explicit binding map. */
@Component
public class AntlrGrammarProvider extends AbstractNeutralGrammarProvider {
    /** Descripción: Inicializa una instancia de AntlrGrammarProvider con sus dependencias y datos de entrada. Entradas: properties: configuración que gobierna el comportamiento. Salida: deja la instancia inicializada y lista para su uso. */ public AntlrGrammarProvider(GrammarProperties properties) { super(properties); }

    /** Descripción: Ejecuta la operación «descriptor» correspondiente a la responsabilidad de AntlrGrammarProvider. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ @Override public GrammarProviderDescriptor descriptor() {
        return new GrammarProviderDescriptor("antlr", GrammarTechnology.ANTLR, "ANTLR", "hydra-provider-1.0",
                new GrammarProviderCapabilities(EnumSet.of(
                        GrammarProviderCapability.ANALYZE, GrammarProviderCapability.CODE_ACTIONS,
                        GrammarProviderCapability.SEMANTIC_MAPPING, GrammarProviderCapability.PROJECT_GENERATION,
                        GrammarProviderCapability.TEXTUAL_RUNTIME, GrammarProviderCapability.DOCUMENT_SYMBOLS,
                        GrammarProviderCapability.LEXER_PARSER, GrammarProviderCapability.VISITOR_LISTENER,
                        GrammarProviderCapability.STANDALONE_WEB, GrammarProviderCapability.STANDALONE_DESKTOP),
                        List.of("Java","TypeScript"), List.of("maven","npm"),
                        EnumSet.of(GrammarProviderCapability.ANALYZE, GrammarProviderCapability.CODE_ACTIONS,
                                GrammarProviderCapability.SEMANTIC_MAPPING, GrammarProviderCapability.PROJECT_GENERATION,
                                GrammarProviderCapability.TEXTUAL_RUNTIME),
                        EnumSet.of(GrammarProviderCapability.DOCUMENT_SYMBOLS, GrammarProviderCapability.LEXER_PARSER,
                                GrammarProviderCapability.VISITOR_LISTENER, GrammarProviderCapability.STANDALONE_WEB,
                                GrammarProviderCapability.STANDALONE_DESKTOP)),
                List.of("FAST","NORMAL","FULL"),
                Map.of("semanticBridge","required-for-model-editor","deployment.browser","TYPESCRIPT_TARGET_ONLY",
                        "deployment.desktop","TARGET_DEPENDENT","ecoreInference","EXPLICIT_MAPPING_ONLY",
                        "tool","ANTLR4_OFFICIAL"));
    }

    /** Descripción: Crea o prepara el resultado de «generateProject» dentro de AntlrGrammarProvider. Entradas: request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public GeneratedGrammarProject generateProject(GrammarProjectGenerationRequest request) {
        String target=request.profile().targetLanguage();
        String version=request.profile().runtimeVersion();
        boolean visitor=Boolean.parseBoolean(request.profile().settings().getOrDefault("visitor","true"));
        boolean listener=Boolean.parseBoolean(request.profile().settings().getOrDefault("listener","true"));
        Map<String,String> scaffold = new LinkedHashMap<>();
        scaffold.put("README.md", "# ANTLR project generated by HYDRA\n\nThe .g4 sources are frozen by snapshot hash. The official ANTLR "+version+" tool generates the parser. Parse-tree nodes require GrammarSemanticBindingMap before promotion to HYDRA semantic elements.\n");
        scaffold.put("hydra-antlr-toolchain.json", "{\n  \"antlrVersion\": \""+json(version)+"\",\n  \"target\": \""+json(target)+"\",\n  \"visitor\": "+visitor+",\n  \"listener\": "+listener+",\n  \"semanticMapping\": \"explicit\",\n  \"generator\": \"org.antlr.v4.Tool\"\n}\n");
        if("Java".equalsIgnoreCase(target)) {
            scaffold.put("pom.xml", javaPom(version,visitor,listener));
            scaffold.put("src/test/java/hydra/generated/HydraAntlrGenerationSmokeTest.java", javaSmoke(request));
        } else {
            scaffold.put("generator-pom.xml", typescriptGeneratorPom(version,visitor,listener,request.documents()));
            scaffold.put("package.json", typescriptPackage(version));
            scaffold.put("tsconfig.json", typescriptConfig());
            scaffold.put("test/generation.test.ts", typescriptSmoke(request));
        }
        scaffold.put("src/HydraSemanticBridge.md", "# Semantic bridge\n\nEvery parser-rule/token mapping must be confirmed in GrammarSemanticBindingMap. Ambiguous target types remain diagnostics and are never invented.\n");
        scaffold.put("HYDRA_PROVENANCE.properties", "grammarId="+propertiesValue(request.grammar().id())+"\nsourceHash="+GrammarHashing.sources(request.documents())+"\ntoolchainProfile="+propertiesValue(request.profile().id())+"\nproviderVersion="+propertiesValue(request.profile().providerVersion())+"\ntarget="+propertiesValue(target)+"\ngenerator=ANTLR4_OFFICIAL\n");
        return project(request, scaffold);
    }

    /** Descripción: Procesa la operación «runtimeDescriptor» coordinando las responsabilidades de AntlrGrammarProvider. Entradas: grammar: dato de entrada necesario para la operación; profile: archivo o contenido que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ @Override public GrammarRuntimeDescriptor runtimeDescriptor(GrammarDefinitionModel grammar, GrammarToolchainProfile profile) {
        boolean browser="TypeScript".equalsIgnoreCase(profile.targetLanguage());
        return new GrammarRuntimeDescriptor(browser?"ANTLR_TYPESCRIPT_PARSER_BRIDGE":"ANTLR_JAVA_PARSER_BRIDGE",grammar.entryRule(),List.of("."+extensionId(grammar.id())),
                browser?"":"java -jar parser-runtime.jar",browser?"./dist/parser-runtime.js":"",
                Map.of("provider","ANTLR","runtimeProfileKey",browser?"antlr-typescript":"antlr-java","providerVersion",profile.providerVersion(),"semanticBridge","required","offlinePwa",Boolean.toString(browser),"generator","ANTLR4_OFFICIAL"));
    }
    /** Descripción: Ejecuta la operación «syntaxMetadata» correspondiente a la responsabilidad de AntlrGrammarProvider. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ @Override public GrammarSyntaxMetadata syntaxMetadata() { return new GrammarSyntaxMetadata("antlr", List.of("grammar","lexer","parser","fragment","returns","locals","mode","channels","tokens","options","import"), Map.of("lexerRule","regexp","parserRule","type"), List.of(".g4")); }

    /** Descripción: Ejecuta la operación «javaPom» correspondiente a la responsabilidad de AntlrGrammarProvider. Entradas: version: dato de entrada necesario para la operación; visitor: dato de entrada necesario para la operación; listener: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static String javaPom(String version,boolean visitor,boolean listener){
        return "<project xmlns=\"http://maven.apache.org/POM/4.0.0\"><modelVersion>4.0.0</modelVersion>"+
                "<groupId>hydra.generated</groupId><artifactId>hydra-antlr-language</artifactId><version>1.0.0-SNAPSHOT</version>"+
                "<properties><maven.compiler.release>17</maven.compiler.release><project.build.sourceEncoding>UTF-8</project.build.sourceEncoding><antlr.version>"+xml(version)+"</antlr.version></properties>"+
                "<dependencies><dependency><groupId>org.antlr</groupId><artifactId>antlr4-runtime</artifactId><version>${antlr.version}</version></dependency>"+
                "<dependency><groupId>org.junit.jupiter</groupId><artifactId>junit-jupiter</artifactId><version>5.12.2</version><scope>test</scope></dependency></dependencies>"+
                "<build><plugins><plugin><groupId>org.antlr</groupId><artifactId>antlr4-maven-plugin</artifactId><version>${antlr.version}</version>"+
                "<executions><execution><goals><goal>antlr4</goal></goals><configuration><sourceDirectory>${project.basedir}</sourceDirectory><outputDirectory>${project.build.directory}/generated-sources/antlr4</outputDirectory><visitor>"+visitor+"</visitor><listener>"+listener+"</listener><includes><include>**/*.g4</include></includes></configuration></execution></executions></plugin>"+
                "<plugin><groupId>org.apache.maven.plugins</groupId><artifactId>maven-surefire-plugin</artifactId><version>3.5.3</version></plugin></plugins></build></project>\n";
    }

    /** Descripción: Ejecuta la operación «typescriptGeneratorPom» correspondiente a la responsabilidad de AntlrGrammarProvider. Entradas: version: dato de entrada necesario para la operación; visitor: dato de entrada necesario para la operación; listener: dato de entrada necesario para la operación; documents: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static String typescriptGeneratorPom(String version,boolean visitor,boolean listener,List<GrammarSourceDocument> documents){
        String visitorArg=visitor?"<argument>-visitor</argument>":"<argument>-no-visitor</argument>";
        String listenerArg=listener?"<argument>-listener</argument>":"<argument>-no-listener</argument>";
        StringBuilder sources=new StringBuilder();
        documents.stream().map(GrammarSourceDocument::relativePath).filter(path->path.toLowerCase(Locale.ROOT).endsWith(".g4")).sorted().forEach(path->sources.append("<argument>").append(xml(path)).append("</argument>"));
        if(sources.isEmpty())throw new IllegalArgumentException("ANTLR project generation requires at least one .g4 document");
        return "<project xmlns=\"http://maven.apache.org/POM/4.0.0\"><modelVersion>4.0.0</modelVersion><groupId>hydra.generated</groupId><artifactId>hydra-antlr-typescript-generator</artifactId><version>1.0.0-SNAPSHOT</version>"+
                "<properties><antlr.version>"+xml(version)+"</antlr.version></properties><dependencies><dependency><groupId>org.antlr</groupId><artifactId>antlr4</artifactId><version>${antlr.version}</version></dependency></dependencies>"+
                "<build><plugins><plugin><groupId>org.codehaus.mojo</groupId><artifactId>exec-maven-plugin</artifactId><version>3.5.0</version><executions><execution><id>generate-typescript</id><phase>generate-sources</phase><goals><goal>java</goal></goals><configuration><mainClass>org.antlr.v4.Tool</mainClass><classpathScope>compile</classpathScope><arguments><argument>-Dlanguage=TypeScript</argument>"+visitorArg+listenerArg+"<argument>-o</argument><argument>src/generated</argument>"+sources+"</arguments></configuration></execution></executions></plugin></plugins></build></project>\n";
    }

    /** Descripción: Ejecuta la operación «typescriptPackage» correspondiente a la responsabilidad de AntlrGrammarProvider. Entradas: version: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static String typescriptPackage(String version){return "{\n  \"name\": \"hydra-antlr-language\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"scripts\": {\"build\": \"tsc -p tsconfig.json\", \"test\": \"vitest run\"},\n  \"dependencies\": {\"antlr4\": \""+json(version)+"\"},\n  \"devDependencies\": {\"typescript\": \"^5.8.0\", \"vitest\": \"^4.0.0\"}\n}\n";}
    /** Descripción: Ejecuta la operación «typescriptConfig» correspondiente a la responsabilidad de AntlrGrammarProvider. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ private static String typescriptConfig(){return "{\n  \"compilerOptions\": {\"target\": \"ES2022\", \"module\": \"NodeNext\", \"moduleResolution\": \"NodeNext\", \"strict\": true, \"outDir\": \"dist\", \"skipLibCheck\": true},\n  \"include\": [\"src/generated/**/*.ts\"]\n}\n";}
    /** Descripción: Ejecuta la operación «javaSmoke» correspondiente a la responsabilidad de AntlrGrammarProvider. Entradas: request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static String javaSmoke(GrammarProjectGenerationRequest request){return "package hydra.generated; import static org.junit.jupiter.api.Assertions.*; import java.nio.file.*; import org.junit.jupiter.api.Test; class HydraAntlrGenerationSmokeTest { @Test void frozenGrammarAndGeneratedSourcesExist() throws Exception { assertTrue(Files.walk(Path.of(\"target/generated-sources/antlr4\")).anyMatch(p->p.toString().endsWith(\".java\"))); assertFalse(\""+javaString(request.profile().id())+"\".isBlank()); } }\n";}
    /** Descripción: Ejecuta la operación «typescriptSmoke» correspondiente a la responsabilidad de AntlrGrammarProvider. Entradas: request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static String typescriptSmoke(GrammarProjectGenerationRequest request){return "import { describe, expect, it } from 'vitest';\nimport { readdirSync } from 'node:fs';\ndescribe('ANTLR generation',()=>it('produces TypeScript parser artifacts',()=>{const files=readdirSync('src/generated',{recursive:true}).map(String);expect(files.some(file=>file.endsWith('.ts'))).toBe(true);expect('"+jsString(request.profile().id())+"').not.toBe('');}));\n";}
    /** Descripción: Ejecuta la operación «extensionId» correspondiente a la responsabilidad de AntlrGrammarProvider. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String extensionId(String value){String result=(value==null?"":value).toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","");return result.isBlank()?"dsl":result;}
    /** Descripción: Ejecuta la operación «json» correspondiente a la responsabilidad de AntlrGrammarProvider. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String json(String value){return value==null?"":value.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r");}
    /** Descripción: Ejecuta la operación «xml» correspondiente a la responsabilidad de AntlrGrammarProvider. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String xml(String value){return value==null?"":value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
    /** Descripción: Ejecuta la operación «javaString» correspondiente a la responsabilidad de AntlrGrammarProvider. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String javaString(String value){return value==null?"":value.replace("\\","\\\\").replace("\"","\\\"").replace("\n"," ").replace("\r"," ");}
    /** Descripción: Ejecuta la operación «jsString» correspondiente a la responsabilidad de AntlrGrammarProvider. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String jsString(String value){return value==null?"":value.replace("\\","\\\\").replace("'","\\'").replace("\n"," ").replace("\r"," ");}
    /** Descripción: Ejecuta la operación «propertiesValue» correspondiente a la responsabilidad de AntlrGrammarProvider. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String propertiesValue(String value){return value==null?"":value.replace("\n"," ").replace("\r"," ").replace("=","\\=");}
}
